actor Greeter {
    let prefix: String
    init(prefix: String) { self.prefix = prefix }
    nonisolated var greetingTag: String {
        "[\(prefix)]"
    }
}

let g = Greeter(prefix: "VIP")
print(g.greetingTag)

actor ScoreTracker {
    var score = 10
    func add(points: Int) { score += points }
    func current() -> Int { score }
}

func run() async {
    let tracker = ScoreTracker()
    await tracker.add(points: 15)
    print("Score: \(await tracker.current())")
}
await run()

@MainActor
final class TitleModel {
    var title = "Home"
    func setTitle(_ newTitle: String) {
        title = newTitle
    }
}

nonisolated func check() async {
    let model = TitleModel()
    await model.setTitle("Settings")
    print("Title: \(await model.title)")
}
await check()

actor SafeVault {
    private var balance = 100
    func withdraw(amount: Int) -> Bool {
        if balance >= amount {
            balance -= amount
            return true
        }
        return false
    }
}

func runVault() async {
    let vault = SafeVault()
    let s1 = await vault.withdraw(amount: 70)
    let s2 = await vault.withdraw(amount: 50)
    print("Results: \(s1), \(s2)")
}
await runVault()

actor Storage {
    var items: [String] = []
    func save(_ item: String) { items.append(item) }
    func all() -> [String] { items }
}

func execute() async {
    let s = Storage()
    await s.save("A")
    await s.save("B")
    let count = await s.all().count
    print("Count: \(count)")
}
await execute()

actor Multiplier {
    let factor: Int
    init(factor: Int) { self.factor = factor }
    func multiply(_ val: Int) -> Int { val * factor }
}

func run() async {
    let m = Multiplier(factor: 3)
    let result = await m.multiply(4)
    print("Result: \(result)")
}
await run()

