@MainActor
final class UserSettings {
    var theme = "Light"
    func toggleTheme() {
        theme = (theme == "Light") ? "Dark" : "Light"
    }
}

nonisolated func run() async {
    let settings = UserSettings()
    await settings.toggleTheme()
    print("Theme: \(await settings.theme)")
}

await run()
